import math
from typing import List
class Solution:
    def minSizeSubarray(self, nums: List[int], target: int) -> int:
        n, total = len(nums), sum(nums)
        arr = nums + nums
        pref = [0]
        for v in arr:
            pref.append(pref[-1] + v)
        first = {}
        for i, p in enumerate(pref):
            if p not in first:
                first[p] = i
        def shortest(need):
            best = math.inf
            for r in range(len(arr)):
                j = first.get(pref[r + 1] - need)
                if j is not None:
                    best = min(best, r + 1 - j)
            return best
        q, rem = divmod(target, total)
        ans = math.inf
        for j in (q, q - 1):
            if j >= 0:
                L = shortest(target - j * total)
                if L <= 2 * n:
                    ans = min(ans, j * n + L)
        return ans if ans != math.inf else -1

