class Solution {
public:
    int minSizeSubarray(vector<int>& nums, int target) {
        int n = nums.size();
        long long total = accumulate(nums.begin(), nums.end(), 0LL);
        vector<long long> pref{0};
        for (int rep = 0; rep < 2; rep++)
            for (int v : nums) pref.push_back(pref.back() + v);
        unordered_map<long long,int> first;
        for (int i = 0; i < (int)pref.size(); i++)
            if (!first.count(pref[i])) first[pref[i]] = i;
        auto shortest = [&](long long need) {
            long long best = LLONG_MAX;
            for (int r = 0; r < 2 * n; r++) {
                auto it = first.find(pref[r + 1] - need);
                if (it != first.end()) best = min(best, (long long)(r + 1 - it->second));
            }
            return best;
        };
        long long q = target / total, rem = target % total;
        long long ans = LLONG_MAX;
        for (long long j : {q, q - 1}) {
            if (j >= 0) {
                long long L = shortest(target - j * total);
                if (L <= 2LL * n) ans = min(ans, j * n + L);
            }
        }
        return ans == LLONG_MAX ? -1 : (int)ans;
    }
};

