class Solution {
    public int minSizeSubarray(int[] nums, int target) {
        int n = nums.length;
        long total = 0;
        for (int v : nums) total += v;
        long[] pref = new long[2 * n + 1];
        for (int i = 0; i < 2 * n; i++) pref[i + 1] = pref[i] + nums[i % n];
        Map<Long, Integer> first = new HashMap<>();
        for (int i = 0; i <= 2 * n; i++) first.putIfAbsent(pref[i], i);
        long q = target / total;
        long ans = Long.MAX_VALUE;
        for (long j : new long[]{q, q - 1}) {
            if (j < 0) continue;
            long need = target - j * total, best = Long.MAX_VALUE;
            for (int r = 0; r < 2 * n; r++) {
                Integer st = first.get(pref[r + 1] - need);
                if (st != null) best = Math.min(best, r + 1 - st);
            }
            if (best <= 2L * n) ans = Math.min(ans, j * n + best);
        }
        return ans == Long.MAX_VALUE ? -1 : (int) ans;
    }
}

