    const first = new Map();
    pref.forEach((p, i) => { if (!first.has(p)) first.set(p, i); });
    const shortest = (need) => {
        let best = Infinity;
        for (let r = 0; r < 2 * n; r++) {
            const st = first.get(pref[r + 1] - need);
            if (st !== undefined) best = Math.min(best, r + 1 - st);
        }
        return best;
    };
    const q = Math.floor(target / total);
    let ans = Infinity;
    for (const j of [q, q - 1]) {
        if (j >= 0) {
            const L = shortest(target - j * total);
            if (L <= 2 * n) ans = Math.min(ans, j * n + L);
        }
    }
    return ans === Infinity ? -1 : ans;
